//! Shared normalization charges exact direct/COW text and compact child backing.
use super::*;
#[test]
fn shared_normalize_no_slot_copy_retained_refusal_and_actual_shared_storage_ledger(){
 for parked in [false,true]{let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);if !parked{page.state.node_limit=doc.nodes.len();}assert_eq!(page.console_eval(&mut doc,&mut forms,"var owner=new Document(),p=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),a=owner.createTextNode('left'),b=owner.createTextNode('right');p.appendChild(a);p.appendChild(b);").errors,0);let Value::Host(p)=page.runtime.execute("p",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("p")};let Value::Host(a)=page.runtime.execute("a",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("a")};let Value::Host(b)=page.runtime.execute("b",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("b")};page.begin_job();let mut bridge=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};bridge.state.rebuild(bridge.doc).unwrap();let before=(bridge.state.retained,bridge.state.inert_documents.backing_bytes(),bridge.doc.nodes.len(),bridge.state.inert_documents.entries.len(),bridge.state.inert_documents.generated.len(),bridge.state.dom_commits);let copies=bridge.state.copy_work;let limit=bridge.state.retained_limit;bridge.state.copy_work=0;assert!(bridge.prepare_shared_normalize(p).is_err());assert!(bridge.state.normalize_plan.is_none());assert_eq!((bridge.state.retained,bridge.state.inert_documents.backing_bytes(),bridge.doc.nodes.len(),bridge.state.inert_documents.entries.len(),bridge.state.inert_documents.generated.len(),bridge.state.dom_commits),before);bridge.state.copy_work=copies;bridge.prepare_shared_normalize(p).unwrap();bridge.state.retained_limit=0;assert!(bridge.commit_shared_normalize(p).is_err());assert!(bridge.state.normalize_plan.is_none());assert_eq!((bridge.state.retained,bridge.state.inert_documents.backing_bytes(),bridge.doc.nodes.len(),bridge.state.inert_documents.entries.len(),bridge.state.inert_documents.generated.len(),bridge.state.dom_commits),before);assert_eq!(bridge.inert_children(p).unwrap(),[a,b]);bridge.state.retained_limit=limit;bridge.state.copy_work=copies;bridge.prepare_shared_normalize(p).unwrap();let plan=bridge.state.normalize_plan.as_ref().unwrap();let(payload,released)=(plan.payload,plan.released);let registry=bridge.state.inert_documents.entries.capacity()*size_of::<Entry>()+bridge.state.inert_documents.generated.capacity()*size_of::<GeneratedNode>();bridge.commit_shared_normalize(p).unwrap();let after=bridge.state.inert_documents.entries.capacity()*size_of::<Entry>()+bridge.state.inert_documents.generated.capacity()*size_of::<GeneratedNode>();assert_eq!(bridge.state.retained,before.0-released+payload+after-registry);assert_eq!(bridge.inert_children(p).unwrap(),[a]);assert_eq!(bridge.character_data_source(a).unwrap().scalar().unwrap(),"leftright");assert_eq!(bridge.character_data_source(b).unwrap().scalar().unwrap(),"right");assert_eq!(bridge.state.inert_documents.node(b).unwrap().parent,None);assert_eq!(bridge.doc.nodes.len(),before.2);assert_eq!(bridge.state.inert_documents.entries.len(),before.3);assert_eq!(bridge.state.inert_documents.generated.len(),before.4+usize::from(parked));}
}
